from taf.rfrl.l3_call.pcap.pcap import VerifyPcap, VerifyPcapNSA


class VerifyPcapFactory:
    """
    Creates VerifyPcap, VerifyPcapNSA instance
    """

    @staticmethod
    def create_pcap_instance(ran, mode, cell_distname):
        """
        Creates either VerifyPcap, VerifyPcapNSA instance
        depending on ran and mode

        :param ran: RAN type: classical/cloud
        :type ran: str
        :param mode: BTS setup mode SA, NSA or "" for classical EnB configs
        :type mode: str
        :param cell_distname: distname of called cell
        :type cell_distname: str
        :return: VerifyPcap or VerifyPcapNSA instance
        :rtype: VerifyPcap

        """
        if mode == "NSA":
            return VerifyPcapNSA(ran=ran, cell_distname=cell_distname)
        else:
            return VerifyPcap(ran=ran, cell_distname=cell_distname)
